    private static class DescriptionRuleViolationFileNameStrategy implements RuleViolationFileNameStrategy {
        @Override
        public String createRuleFileName(String ruleDescription) {
            List<String> words = new ArrayList<>();
            Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(ruleDescription);
            while (matcher.find()) {
                words.add(matcher.group());
            }

            String hash = hash(ruleDescription);
            int available = 200 - hash.length() - 1;
            List<String> selected = new ArrayList<>();
            int length = 0;
            for (int i = words.size() - 1; i >= 0; i--) {
                String word = words.get(i);
                int addedLength = word.length() + (selected.isEmpty() ? 0 : 1);
                if (length + addedLength > available) {
                    break;
                }
                selected.add(word);
                length += addedLength;
            }
            Collections.reverse(selected);
            String readable = selected.isEmpty() ? "rule" : String.join("_", selected);
            return readable + "_" + hash;
        }

        private static String hash(String value) {
            try {
                byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
                StringBuilder result = new StringBuilder();
                for (byte item : digest) {
                    result.append(String.format("%02x", item & 0xff));
                }
                return result.toString();
            } catch (NoSuchAlgorithmException e) {
                throw new IllegalStateException(e);
            }
        }
    }

